def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data.get("roots", {})
        best = None
        best_versions = None

        # Enumerate installed versions (or absence), then validate the exact
        # active closure and all simultaneous range constraints.
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, []))
            choices.append([None] + versions)

        def check(selection):
            installed = {n for n, v in selection.items() if v is not None}
            for name, bounds in roots.items():
                v = selection.get(name)
                if v is None or not bounds[0] <= v <= bounds[1]:
                    return False
            for name in installed:
                if name in pins and selection[name] != pins[name]:
                    return False

            edges = {n: [] for n in installed}
            ranges = {n: [] for n in installed}
            for name in installed:
                row = next(r for r in packages[name] if r["version"] == selection[name])
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    v = selection.get(other)
                    if v is None or not dep["min"] <= v <= dep["max"]:
                        return False
                    edges[name].append(other)
                    ranges[name].append(other)

            # All and only packages reachable from roots must be installed.
            reachable = set()
            stack = list(roots)
            while stack:
                n = stack.pop()
                if n in reachable:
                    continue
                reachable.add(n)
                if n not in installed:
                    return False
                stack.extend(edges[n])
            if reachable != installed:
                return False

            active, done = set(), set()
            def visit(n):
                if n in active:
                    return False
                if n in done:
                    return True
                active.add(n)
                if any(not visit(x) for x in edges[n]):
                    return False
                active.remove(n)
                done.add(n)
                return True
            return all(visit(n) for n in installed)

        def enumerate_at(i, current):
            nonlocal best, best_versions
            if i == len(names):
                if not check(current):
                    return
                vector = tuple(current.get(n) if current.get(n) is not None else -1
                               for n in sorted(names, reverse=True))
                if best is None or vector < best:
                    best = vector
                    best_versions = {n: v for n, v in current.items() if v is not None}
                return
            name = names[i]
            for version in choices[i]:
                current[name] = version
                enumerate_at(i + 1, current)
            current.pop(name, None)

        enumerate_at(0, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        options = [j for j in jobs if j["id"] not in blocked]
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = [j["id"] for j in subset]
            idset = set(ids)
            if not mandatory <= idset:
                continue
            counts = {}
            for j in subset:
                counts[j["group"]] = counts.get(j["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
            if any(a["end"] > b["start"] for a, b in zip(ordered, ordered[1:])):
                continue
            value = sum(j["value"] for j in subset)
            sorted_ids = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and sorted_ids > best_ids)):
                best_value, best_ids = value, sorted_ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start = data["start"]
        source = data["source"]
        initial_mask = bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        dist = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                v = edge["v"]
                next_mask = mask | bit.get(v, 0)
                options = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = (v, next_mask, left)
                    if arrival < dist.get(nxt, float("inf")):
                        dist[nxt] = arrival
                        heapq.heappush(queue, (arrival, v, next_mask, left))
        return {"arrival": None}
    return solve


